"""TEST_ONLY policy invalidation: generated bytes, no native calls or physical proof."""

import contextlib
import hashlib
import importlib
import importlib.util
import json
import unittest
from unittest.mock import patch

import export_motion as exporter
import pipeline_quality as quality
import run_pipeline as runner
import test_export_motion as export_tests

LEGACY_POLICY = "kinelab.pipeline-quality.v2"
CURRENT_POLICY = "kinelab.pipeline-quality.v4"


class PipelineQualityPolicyV3Tests(unittest.TestCase):
    setUp = export_tests.ExportTests.setUp
    write = export_tests.ExportTests.write

    def snapshot(self):
        return {path.relative_to(self.root).as_posix(): hashlib.sha256(path.read_bytes()).hexdigest()
                for path in self.root.rglob("*") if path.is_file()}

    def legacy_fixture(self):
        # Produce the manifest as v2 from the outset; never rewrite a stored policy or artifact.
        source_coverage = (importlib.import_module('source_coverage')
                           if importlib.util.find_spec('source_coverage') is not None else None)
        historical_source_policy = (patch.object(source_coverage, 'POLICY', LEGACY_POLICY)
                                    if source_coverage is not None else contextlib.nullcontext())
        # Narrow historical producer/acceptor simulation only. Default v4 is
        # restored before every real negative; no production policy bypass.
        with (patch.object(runner, "QUALITY_POLICY", LEGACY_POLICY),
              patch.object(quality, "QUALITY_POLICY", LEGACY_POLICY),
              historical_source_policy):
            manifest = export_tests.ExportTests.manifest(self)
            before = self.snapshot()
            record = json.loads(manifest.read_text(encoding="utf-8"))
            self.assertEqual(record["quality_policy"], LEGACY_POLICY)
            associated = record["stages"][runner.STAGES.index("personAssociation")]["artifacts"]
            self.assertEqual({item["path"].split("/")[1] for item in associated},
                             {"cam01_json", "cam02_json"})
            self.assertEqual(len(associated), 26)  # two cameras, C=[60,73)
            for stage in record["stages"][:runner.STAGES.index("filtering") + 1]:
                actual = runner._artifacts(self.root, stage["name"])
                self.assertEqual(set(actual), {item["path"] for item in stage["artifacts"]})
                for item in stage["artifacts"]:
                    self.assertEqual(actual[item["path"]][0], item["sha256"])
            verified = runner.validate_run_evidence(self.root, "filtering")
            self.assertEqual(verified["run"], record)
            self.assertIsInstance(exporter.bind_run(manifest, self.trc, None), dict)
            self.assertEqual(self.snapshot(), before)
        return manifest, before

    def assert_legacy_unchanged(self, manifest, before):
        self.assertEqual(self.snapshot(), before, "Refusal must not relabel or rewrite legacy evidence")
        record = json.loads(manifest.read_text(encoding="utf-8"))
        self.assertEqual(record["quality_policy"], LEGACY_POLICY)
        for stage in record["stages"]:
            if stage.get("quality", {}).get("policy"):
                self.assertEqual(stage["quality"]["policy"], LEGACY_POLICY)
        self.assertFalse((self.root / "run.lock").exists())

    def test_B14_POLICY_00_producer_and_acceptor_advance_together(self):
        self.assertEqual(quality.QUALITY_POLICY, CURRENT_POLICY)
        self.assertEqual(runner.QUALITY_POLICY, CURRENT_POLICY)

    def test_B14_POLICY_01_unchanged_hash_bound_v2_validation_is_rejected(self):
        manifest, before = self.legacy_fixture()
        for through in ("triangulation", "filtering"):
            with self.subTest(through=through):
                with self.assertRaisesRegex(ValueError, "^QUALITY_POLICY:"):
                    runner.validate_run_evidence(self.root, through)
                self.assert_legacy_unchanged(manifest, before)

    def test_B14_POLICY_02_unchanged_hash_bound_v2_resume_is_rejected_before_native_call(self):
        manifest, before = self.legacy_fixture()
        with patch.object(runner, "_invoke_stage") as native:
            with self.assertRaisesRegex(ValueError, "^QUALITY_POLICY:"):
                runner.run_stages(self.root, "filtering", "filtering")
            native.assert_not_called()
        self.assert_legacy_unchanged(manifest, before)

    def test_B14_POLICY_03_unchanged_hash_bound_v2_export_is_rejected(self):
        manifest, before = self.legacy_fixture()
        with self.assertRaisesRegex(ValueError, "ARTIFACT_MISMATCH:.*QUALITY_POLICY:"):
            exporter.bind_run(manifest, self.trc, None)
        self.assert_legacy_unchanged(manifest, before)

    def test_B14_POLICY_04_unchanged_hash_bound_v3_validate_resume_and_export_refused(self):
        global LEGACY_POLICY
        original = LEGACY_POLICY
        LEGACY_POLICY = "kinelab.pipeline-quality.v3"
        try:
            manifest, before = self.legacy_fixture()
            for through in ("triangulation", "filtering"):
                with self.subTest(through=through), self.assertRaisesRegex(ValueError, "^QUALITY_POLICY:"):
                    runner.validate_run_evidence(self.root, through)
                self.assert_legacy_unchanged(manifest, before)
            with patch.object(runner, "_invoke_stage") as native:
                with self.assertRaisesRegex(ValueError, "^QUALITY_POLICY:"):
                    runner.run_stages(self.root, "markerAugmentation", "markerAugmentation")
                native.assert_not_called()
            with self.assertRaisesRegex(ValueError, "ARTIFACT_MISMATCH:.*QUALITY_POLICY:"):
                exporter.bind_run(manifest, self.trc, None)
            self.assert_legacy_unchanged(manifest, before)
        finally:
            LEGACY_POLICY = original


if __name__ == "__main__":
    unittest.main()